WITH valid_employees AS (SELECT *, CAST(salary AS INT) AS salary_int FROM employees WHERE dept_id = 19 AND hire_date <= '2023-10-02' AND salary >= 118000), employees_stats AS (SELECT QUARTER(hire_date) AS hire_quarter, COUNT(CASE WHEN level = 'L2' THEN 1 END) AS l2_count, ROUND(AVG(salary_int), 2) AS avg_salary_int FROM valid_employees GROUP BY QUARTER(hire_date)) SELECT * FROM employees_stats WHERE avg_salary_int < 70;
